{
  "narratives": [
    {
      "item_code": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해 필요한 조치사항 및 보호구",
      "start": "p3:L21",
      "end": "p3:L29"
    },
    {
      "item_code": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해 필요한 조치사항",
      "start": "p3:L30",
      "end": "p4:L4"
    },
    {
      "item_code": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거방법",
      "start": "p4:L5",
      "end": "p4:L13"
    }
  ],
  "extras": [
    {
      "after_item": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해 필요한 조치사항 및 보호구",
      "reason": "코드없음",
      "statements": [
        {
          "key": "작업자",
          "value": "적절한 보호구(『８. 노출방지 및 개인보호구』항 참조)를 착용하여, 눈 피부에의 접촉과 흡입을 피할 것."
        ,
          "line": "p3:L22"
        },
        {
          "key": "작업자",
          "value": "위험하지 않다면 누출을 멈추시오"
        ,
          "line": "p3:L24"
        },
        {
          "key": "작업자",
          "value": "피해야 할 물질 및 조건에 유의하시오"
        ,
          "line": "p3:L25"
        },
        {
          "key": "작업자",
          "value": "오염지역을 환기하시오"
        ,
          "line": "p3:L26"
        },
        {
          "key": "작업자",
          "value": "노출물을 만지거나 걸어다니지 마시오"
        ,
          "line": "p3:L27"
        },
        {
          "key": "작업자",
          "value": "분진 형성을 방지하시오."
        ,
          "line": "p3:L28"
        },
        {
          "key": "작업자",
          "value": "모든 점화원을 제거하시오."
        ,
          "line": "p3:L29"
        }
      ]
    ,
      "line": "p3:L21"
    },
    {
      "after_item": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해 필요한 조치사항",
      "reason": "코드없음",
      "statements": [
        {
          "key": "작업자",
          "value": "누출물이 하수시설, 수계에 유입되지 않도록 차단시키시오."
        ,
          "line": "p3:L31"
        },
        {
          "key": "작업자",
          "value": "누출량이 많은 경우 119나 환경부, 지방환경관리청, 시·도(환경지도과)에 신고하시오."
        ,
          "line": "p4:L3"
        },
        {
          "key": "작업자",
          "value": "기준량 이상 배출 시 중앙정부, 지방자치단체에 배출 내용을 통지하시오."
        ,
          "line": "p4:L8"
        }
      ]
    ,
      "line": "p3:L30"
    },
    {
      "after_item": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거방법",
      "reason": "코드없음",
      "statements": [
        {
          "key": "다량누출",
          "value": "저지대를 피하고 바람과 반대방향에 있도록 하시오. 누출물질의 처리를 위해 제방을 축조하여 관리하시오."
        ,
          "line": "p4:L6"
        },
        {
          "key": "작업자",
          "value": "폐기물관리법(환경부)에 의해 처리하시오."
        ,
          "line": "p4:L9"
        },
        {
          "key": "작업자",
          "value": "누출된 물질의 처분을 위해 적당한 용기에 수거하시오."
        ,
          "line": "p4:L10"
        },
        {
          "key": "작업자",
          "value": "작은 고체상 유출: 누출된 물질의 처분을 위해 적당한 용기에 수거하시오."
        ,
          "line": "p4:L11"
        },
        {
          "key": "작업자",
          "value": "누출된 물질은 적당한 용기에 쓸어 담고 오염된 장소를 청소하시오."
        ,
          "line": "p4:L13"
        }
      ]
    ,
      "line": "p4:L5"
    }
  ]
}

